    def fmt(v):
        return str(len(v)) + '\n' + ' '.join(map(str, v))
    tests = [fmt([7]), fmt([-100, 100]), fmt([0, 1]), fmt([3, 1, 2])]
    for n in (2, 3, 4, 5, 6, 7, 8):
        for _ in range(2):
            tests.append(fmt(rng.sample(range(-100, 101), n)))
    tests.append(fmt(rng.sample(range(-100, 101), 9)))
    for _ in range(3):
        tests.append(fmt(rng.sample(range(-100, 101), 12)))
    tests.append(fmt([-100 + 17 * i for i in range(12)]))
    tests.append(fmt([100 - 19 * i for i in range(12)]))
    return tests

